#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.."&&pwd)";cd "$root";b=build/guards/phase16_cross_module_abi;r=/tmp/gust-phase16-cross-module-abi.request;m=/tmp/gust-phase16-cross-module-abi.mir-to-c.witness;w=compiler/experiments/cranelift/target/debug/gust-cranelift-experiment;mkdir -p "$b";trap 's=$?;echo "Phase 16.11 cross-module parity failed status=$s line=$LINENO" >&2;exit $s' ERR
bash scripts/run-gust-file.sh compiler/mir_cross_module_abi_smoke_test_entry.gst;rg -F 'SUCCESS: Phase 16.11 cross-module ABI smoke passed' to.log >/dev/null;cargo build --manifest-path compiler/experiments/cranelift/Cargo.toml >"$b/cargo.log" 2>&1;"$w" phase16-cross-module-abi-witness "$r">"$b/witness";cmp -s "$m" "$b/witness"
reject(){ cp "$r" "$b/$1.request";sed -i "$3" "$b/$1.request";printf 'sentinel: preserve-existing-output\n'>"$b/$1.output";if "$w" phase16-cross-module-abi-witness "$b/$1.request" >"$b/$1.tmp" 2>"$b/$1.stderr";then false;fi;rg -F "reason=$2" "$b/$1.stderr">/dev/null;rg -F 'sentinel: preserve-existing-output' "$b/$1.output">/dev/null;}
reject stale cross_module_stale_import '0,/same_version=1/ s/same_version=1/same_version=0/';reject layout cross_module_layout_mismatch '0,/import_layout=layout:aggregate_parameter/ s/import_layout=layout:aggregate_parameter/import_layout=layout:wrong/';reject target cross_module_target_mismatch '0,/import_target=target:x86_64/ s/import_target=target:x86_64/import_target=target:wrong/';reject cc cross_module_calling_convention_mismatch '0,/import_cc=gust_canonical_v1/ s/import_cc=gust_canonical_v1/import_cc=wrong/';reject hidden cross_module_hidden_result_mismatch '/scenario=aggregate_result/ s/import_hidden=1/import_hidden=0/';reject resource cross_module_resource_policy_mismatch '/scenario=resource_aggregate_transfer/ s/import_resource=move_only_exact_transfer/import_resource=copy/';reject foreign cross_module_unsupported_foreign_symbol '0,/foreign=0/ s/foreign=0/foreign=1/';echo "guard-cranelift-phase16-cross-module-abi-parity: ok (Level 2)"
